"""Read-only actual capture inspector, prepared only. Writes a new /tmp report.
Never executes a producer/test, installs a fixture, transforms/rebases captured bytes,
or removes an original/artifact root. Passing checks are not independent acceptance.
"""
from pathlib import Path,PurePosixPath
import sys,json,hashlib,base64,xml.etree.ElementTree as ET,re,datetime
COMPILED='0b721c7c37207f1f1622172351fd515150eaf18d';PRODUCT='46ff637a01390a27c45a7fc36dc30e31d688e499'
PROFILE='client_profile/qte_showcase_rewards.json';MEMBER='game_session/game_state/meta/retirement-ordinary-member.bin'
BEFORE=bytes([0xEF,0xBB,0xBF,0,0xFF,41]);AFTER=bytes([0xD0,0x94,0,0xFF,42]);NS={'t':'http://microsoft.com/schemas/VisualStudio/TeamTest/2010'}
EXPECTED={'OriginalCurrentBrowserProducer_CapturesPendingExternalMember':'browser7','OriginalStandaloneProfileProducer_CapturesCommittedCleanupDebt':'standalone1'}
def sha(b):return hashlib.sha256(b).hexdigest()
def main():
 assert len(sys.argv)==3,'actual record and NEW /tmp inspection-report path required'
 record_path,report_path=map(Path,sys.argv[1:]);assert report_path.is_absolute() and str(report_path).startswith('/tmp/') and not report_path.exists()
 record_bytes=record_path.read_bytes();r=json.loads(record_bytes);issues=[];observed={};packets=[]
 def check(ok,label):
  if not ok:issues.append(label)
 def jlines(text):
  for line in text.splitlines():
   line=line.strip()
   if line.startswith('{'):
    try:yield json.loads(line)
    except json.JSONDecodeError:pass
 check(r['category']=='daren-retirement-producer-capture','wrong-category');check(r['compiledSource']==COMPILED and r['productSource']==PRODUCT,'wrong-source-binding')
 check(r['argv']==['pwsh','-NoLogo','-NoProfile','-File','scripts/test-csharp.ps1','-Category',r['category'],'-NoBuild'],'wrong-argv')
 check(r['nativeExit']==0 and r['launchError'] is None,'native-or-launch-failure');check(r['headAfter']==r['actualSource'] and not r['statusAfter'],'head-or-clean-status-changed')
 check(len(r['binaryBefore'])==7 and r['binaryBefore']==r['binaryAfter'],'seven-binary-continuity')
 root=Path(r['cwd'])
 for pin in r['binaryAfter']:check(sha((root/pin['path']).read_bytes())==pin['sha256'],'live-binary:'+pin['path'])
 for pin in r['resultFiles']+r['fixtureArtifactFiles']:
  b=Path(pin['path']).read_bytes();check(len(b)==pin['bytes'] and sha(b)==pin['sha256'],'raw-chain:'+pin['path'])
 check(sha(Path(r['stdoutPath']).read_bytes())==r['stdoutSha256'],'native-stdout-hash')
 check(len(r['resultDirectories'])==1,'result-directory-count');declarations=[];cleanups=[];case_names=[]
 for directory in r['resultDirectories']:
  directory=Path(directory);s=json.loads((directory/'summary.json').read_text(encoding='utf-8-sig'));p=json.loads((directory/'plan.json').read_text(encoding='utf-8-sig'));observed['summary']=s;observed['plan']=p
  check(s['Tests']==dict(Total=2,Executed=2,Passed=2,Failed=0),'summary-counts');sel=s['Selection'];check(sel['PlannedDescriptors']==sel['CompletedDescriptors']==1 and sel['PlannedCases']==sel['CompletedCases']==2 and sel['Complete'] and not sel['UnderfilledDescriptors'],'planned-completed-exact')
  check(not s['TimedOut'] and s['OwnedTreeCleanupSucceeded'] and s['RuntimeCleanupSucceeded'] and not s['DuplicateTests'],'runner-cleanup-timeout-duplicates')
  check(p['Categories']==[r['category']] and len(p['Descriptors'])==1,'singleton-plan')
  desc=p['Descriptors'][0];check(desc['EstimatedCases']==2 and {m['Name'].rsplit('.',1)[-1] for m in desc['ExpectedMethodCounts']}==set(EXPECTED),'exact-two-planned-methods')
  trxs=sorted(directory.rglob('*.trx'));check(len(trxs)==1,'trx-count')
  for trx in trxs:
   t=ET.parse(trx).getroot();counter=t.find('t:ResultSummary/t:Counters',NS);check(counter is not None and all(int(counter.get(k,'-1'))==v for k,v in dict(total=2,executed=2,passed=2,failed=0).items()),'trx-counters')
   definitions={u.attrib['id']:u.find('t:TestMethod',NS) for u in t.findall('t:TestDefinitions/t:UnitTest',NS)}
   results=t.findall('t:Results/t:UnitTestResult',NS);check(len(results)==2 and len({x.get('testId') for x in results})==2,'trx-unique-two-results')
   for result in results:
    method=definitions.get(result.get('testId'));name=method.get('name') if method is not None else result.get('testName','').rsplit('.',1)[-1];case_names.append(name);check(name in EXPECTED and result.get('outcome')=='Passed','trx-case:'+str(name))
    stdout=result.findtext('t:Output/t:StdOut','',NS)
    for row in jlines(stdout):
     if 'RetirementCapture' in row:declarations.append(dict(row,TestMethod=name))
     if 'CleanupOwnedRoot' in row:cleanups.append(dict(row,TestMethod=name))
 check(sorted(case_names)==sorted(EXPECTED),'case-identity-set');check(len(declarations)==len(cleanups)==2,'capture-cleanup-declarations')
 check(len({x['OriginalRoot'] for x in declarations})==2,'unique-original-roots')
 for decl in declarations:
  path=Path(decl['RetirementCapture']);check(path.parent.name.startswith('boe-daren-retirement-artifacts-') and str(path.parent) in r['newRetainedArtifactDirectories'],'artifact-path-ownership')
  check(any(x['path']==str(path) for x in r['fixtureArtifactFiles']),'artifact-recorded');raw=path.read_bytes();check(sha(raw)==decl['Sha256'].lower(),'declared-packet-sha')
  packet=json.loads(raw);kind=packet['Kind'];check(kind==EXPECTED.get(decl['TestMethod'])==decl['Kind'],'packet-kind-lineage');check(packet['ProductSource']==PRODUCT,'original-product-source')
  original=packet['OriginalRoot'];check(original==decl['OriginalRoot'] and Path(original).parent==Path('/tmp') and Path(original).name.startswith('boe-daren-retirement-capture-'),'original-root-lineage');check(not Path(original).exists(),'original-root-still-present')
  receipt=[x for x in cleanups if x['CleanupOwnedRoot']==original and x['TestMethod']==decl['TestMethod']];check(len(receipt)==1 and receipt[0]['OwnedFixtureRemoved'] and receipt[0]['CleanupFailure'] is None,'strict-root-cleanup:'+kind)
  generation=packet['Generation'];check(re.fullmatch('[0-9a-f]{32}',generation) is not None and generation==decl['Generation'],'generation-lineage')
  images={}
  check(set(packet['FilesBase64'])==set(packet['Sha256']),'image-key-hash-set')
  for relative,encoded in packet['FilesBase64'].items():
   pp=PurePosixPath(relative);check(not pp.is_absolute() and '..' not in pp.parts,'relative-image-path:'+relative);body=base64.b64decode(encoded,validate=True);check(sha(body)==packet['Sha256'][relative].lower(),'image-hash:'+relative);images[relative]=body
  check(PROFILE in images and images[PROFILE]==AFTER,'raw-profile-after-nonutf8:'+kind)
  check(MEMBER in images and images[MEMBER]==(AFTER if kind=='browser7' else BEFORE),'actual-ordinary-member-image:'+kind)
  check(packet['GenerationPath']=='.boe_runtime/session-generation/current.json','actual-generation-path');gen=json.loads(images[packet['GenerationPath']]);check(set(gen)=={'SchemaVersion','GenerationId'} and gen['SchemaVersion']==1 and gen['GenerationId']==generation,'physical-current-generation-binding')
  evidence=packet['EvidencePath'];body=json.loads(images[evidence]);details={}
  if kind=='browser7':
   check(evidence.endswith('/browser_write_manifest.json') and evidence.startswith('game_session/game_state/control/explorer_local_turn_rollback/retirement_capture/'),'browser-evidence-path')
   check(body['schemaVersion']==7 and body['transactionKind']=='browser_local_write' and body['status']=='staged' and body['generation']==generation,'browser7-real-staged-binding')
   check(len(body['entries'])==len(body['externalEntries'])==1,'actual-browser-member-counts')
   member=body['entries'][0];ext=body['externalEntries'][0];check(member['trackedFile']=='game_state/meta/retirement-ordinary-member.bin' and ext['fileId']=='daren_reward_profile','browser-registered-members')
   for entry,label in [(member,'ordinary'),(ext,'profile')]:
    check(entry['existed'] is True,'browser-before-existed:'+label);backup='game_session/'+entry['backupPath'];check(images.get(backup)==BEFORE and entry['sha256'].lower()==sha(BEFORE),'raw-original-backup:'+label)
   details=dict(schema=body['schemaVersion'],status=body['status'],externalId=ext['fileId'],memberCount=1,externalCount=1,actualOrdinaryAndProfileBefore=sha(BEFORE),physicalOrdinaryAndProfileAfter=sha(AFTER))
  elif kind=='standalone1':
   check(evidence=='.boe_runtime/trusted-local-publication-v1/active.json','standalone-evidence-path');check(body['Format'] in [1,2] and body['Committed'] is True,'actual-standalone-committed-journal')
   check(len(body['Members'])==1,'standalone-single-profile-member');member=body['Members'][0];check(member['Path']==str(Path(original)/PROFILE),'standalone-actual-absolute-profile')
   for key,expected in [('Before',BEFORE),('After',AFTER)]:
    image=member[key];check(image['Exists'] is True and base64.b64decode(image['Bytes'],validate=True)==expected and image['Sha256'].lower()==sha(expected),'standalone-image:'+key)
   check(all(body[key]['Exists'] is True and body[key]['Id']==generation for key in ['GenerationBefore','GenerationAfter']),'standalone-original-generation-binding')
   details=dict(format=body['Format'],committed=body['Committed'],members=1,actualPath=member['Path'],before=sha(BEFORE),after=sha(AFTER))
  packets.append(dict(path=str(path),sha256=sha(raw),bytes=len(raw),kind=kind,originalRoot=original,physicalRootAbsent=not Path(original).exists(),generation=generation,evidencePath=evidence,imagePins=[dict(path=k,bytes=len(v),sha256=sha(v)) for k,v in images.items()],details=details,provenance=packet['Producer']))
 allowed=set(r['newRetainedArtifactDirectories']);check(len(allowed)==2,'retained-diagnostic-count');check(set(r['ownedPrefixesAfter'])-set(r['ownedPrefixesBefore'])==allowed,'only-expected-new-diagnostics');check(set(r['ownedPrefixesBefore'])<=set(r['ownedPrefixesAfter']),'preexisting-namespace-changed')
 report=dict(kind='READ_ONLY_CAPTURE_RAW_INSPECTION_NOT_INDEPENDENT_VERDICT',utc=datetime.datetime.now(datetime.timezone.utc).isoformat(),recordPath=str(record_path),recordSha256=sha(record_bytes),actualSource=r['actualSource'],compiledSource=COMPILED,productSource=PRODUCT,nativeExit=r['nativeExit'],issues=issues,status='RAW_CHECKS_PASSED_NOT_INDEPENDENT_ACCEPTANCE' if not issues else 'FIRST_OUTCOME_REQUIRES_CAUSAL_OR_FIXTURE_CLASSIFICATION',packets=packets,caseNames=case_names,strictCleanupReceipts=cleanups,resultPaths=r['resultDirectories'],observedSummaryAndPlan=observed,helperText=Path(__file__).read_text(),limits=['No consumer recovery, data rebasing/transformation or fixture installation was executed by this inspector.','Exact original-root packet bytes are preserved; deleted test root is not a reusable live authority.','Shared mixed/synthetic schema6 controls are distinct future provenance, never these authentic original packets.'])
 with report_path.open('x') as f:json.dump(report,f,indent=2);f.write('\n')
 print('CAPTURE_RAW_INSPECTION',report['status'],'issues',len(issues),'report',report_path)
 if issues:sys.exit(1)
if __name__=='__main__':main()
